package com.mahweb.mahyarnfc.omnishare.ble;
import android.bluetooth.*; import android.bluetooth.le.*; import android.content.Context; import android.os.*; import android.os.ParcelUuid; import java.util.*;
public final class BleAdvertiser implements AutoCloseable { public interface Listener{void onStarted();void onFailed(int code,String message);void onStopped();} private final Context ctx;private final EphemeralTokenProvider tokens;private final int caps;private final Handler h=new Handler(Looper.getMainLooper());private BluetoothLeAdvertiser adv;private AdvertiseCallback cb;private boolean running;private final Runnable rotate=()->{if(running){stopInternal(false);start();}};private Listener listener;
 public BleAdvertiser(Context c,EphemeralTokenProvider t,int capabilities,Listener l){ctx=c.getApplicationContext();tokens=t;caps=capabilities;listener=l;}
 public void start(){try{BluetoothManager m=(BluetoothManager)ctx.getSystemService(Context.BLUETOOTH_SERVICE);BluetoothAdapter a=m==null?null:m.getAdapter();adv=a==null?null:a.getBluetoothLeAdvertiser();if(adv==null){fail(-1,"BLE advertising unavailable");return;}byte[]sd=BleProtocol.serviceData(caps,tokens.currentToken(System.currentTimeMillis()));AdvertiseSettings st=new AdvertiseSettings.Builder().setAdvertiseMode(AdvertiseSettings.ADVERTISE_MODE_LOW_LATENCY).setTxPowerLevel(AdvertiseSettings.ADVERTISE_TX_POWER_MEDIUM).setConnectable(true).setTimeout(0).build();AdvertiseData data=new AdvertiseData.Builder().addServiceUuid(new ParcelUuid(BleProtocol.SERVICE_UUID)).addServiceData(new ParcelUuid(BleProtocol.SERVICE_UUID),sd).setIncludeDeviceName(false).build();cb=new AdvertiseCallback(){public void onStartSuccess(AdvertiseSettings s){running=true;h.removeCallbacks(rotate);h.postDelayed(rotate,300000L);if(listener!=null)listener.onStarted();}public void onStartFailure(int e){running=false;fail(e,"BLE advertise failed");}};adv.startAdvertising(st,data,cb);}catch(SecurityException e){fail(-2,"Bluetooth permission denied");}}
 private void fail(int c,String m){if(listener!=null)listener.onFailed(c,m);} private void stopInternal(boolean notify){h.removeCallbacks(rotate);if(adv!=null&&cb!=null)try{adv.stopAdvertising(cb);}catch(SecurityException ignored){}boolean was=running;running=false;cb=null;if(notify&&was&&listener!=null)listener.onStopped();} public void close(){stopInternal(true);} }
